from taf.ul.ettf.ta_matchers.matcher_wraper import MatcherWraper
from taf.ul.ettf.logger import custom_logger


logger = custom_logger('ConditionResolver')


class AdditionalRequirement(object):
    def __init__(self, call, negate_result):
        self.call = call
        self.negate_result = negate_result


additional_requirements_call_map = {
    MatcherWraper: AdditionalRequirement('no_all_matchers_left', False),
    'default': AdditionalRequirement(lambda: None, True)
}


class UnsupportedAdditionalRequirementType(Exception):
    pass


class AdditionalRequirements(object):
    @staticmethod
    def check(condition):
        additional_requirement = AdditionalRequirements.get_requirement(condition)
        result = AdditionalRequirements.run_requirement(condition, additional_requirement.call)
        return not result if additional_requirement.negate_result else result

    @staticmethod
    def get_requirement(condition):
        try:
            return additional_requirements_call_map[condition.__class__]
        except KeyError:
            for key in additional_requirements_call_map:
                if not isinstance(key, str) and isinstance(condition.__class__, type(key)):
                    return additional_requirements_call_map[key]
            return additional_requirements_call_map['default']

    @staticmethod
    def run_requirement(condition, requirement):
        if isinstance(requirement, str):
            return condition.__getattribute__(requirement)()
        elif callable(requirement):
            return requirement()
        raise UnsupportedAdditionalRequirementType(type(requirement))


class ConditionResolver(object):
    def __init__(self, condition):
        self.condition = condition
        self.last_result = False

    def get_last_result(self):
        return self.last_result

    def get_result(self, packet):
        return self._get_result(packet), AdditionalRequirements.check(self.condition)

    def _get_result(self, packet):
        if callable(self.condition):
            self.last_result = self.condition(packet)
        else:
            self.last_result = self.condition.matches(packet)
        return self.last_result
